// === Tab: mySketch ===
/**
 * This combines p5 with Shader Park: https://shaderpark.com/
 * to draw via an SDF. Now that p5 has WebGL 2 support, you can
 * use Shader Park SDFs in p5 and even have your p5 shapes draw in front
 * of and behind them! Huge thanks to Dave Pagurek for his help on this!
 * 
 * If you want to try Shader Park in a p5 sketch of your own, make sure
 * to add this library to the list of enabled libraries on OpenProcessing:
 * https://cdn.jsdelivr.net/npm/shader-park-core/dist/shader-park-p5.js
 * - Torin Blankensmith, creator of Shader Park
 **/


let sdf;

function setup() {
  createCanvas(1112, 834, WEBGL);
	pixelDensity(1); // increase for higher quality, decrease for speed
	// `createShaderPark` takes in a function that defines a shape using
	// the Shader Park API available here:
	// https://docs.shaderpark.com/references-js/
	// shaderParkCode is loaded in from shaderParkCode.js
	// Shader Park will convert the javascript into a shader for you

	sdf = createShaderPark(shaderParkCode, {
		//uniformly scale your entire shader park scene
		scale: .8, // reduce this value if your scene is cut off at the edges
		// control what geometry the shader gets applied to
		drawGeometry: () => sphere(120) // increase this value to enlarge the scene
	});
}

function draw() {
  //clear();
	background(255);
	noStroke();
	orbitControl();

	// The Shader Park distance field is drawn to an invisible sphere.
	// A good practice is to keep your coordinate space in Shader Park
	// close to (0, 0, 0) and then move the sdf around later on with P5
	rotateX(PI);
	scale(3);
	push();
  sdf.draw();
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: shaderParkCode.js ===
// Shader Park API available here:
// https://docs.shaderpark.com/references-js/

// Note: this function is treated as a string, so you will
// not be able to access constants you define outside this function
// Shader Park will convert this code into a shader for you.
function shaderParkCode() {
	/*copied from Double-D Shader
  Project #1 by rbytes
  forked from -NfIwgSfF69x5Nv_KnCc*/

  let yModifier = 0;
  let angleModifier = 0
  function generateSpinner(yModifier, angleMod){
    let xRotationValue = tan(time + angleMod) * cos(time + angleMod) / 16;
    let zRotationValue = cos(time + angleMod) / 16;
    for (let delta = 0; delta < 6; delta++){
      displace(xRotationValue, yModifier / 35, zRotationValue);
      metal(3);
      let col = hsv2rgb(vec3((yModifier/6), 1, 1));
      color(col);
      sphere(0.05);
    }
  	displace(-xRotationValue*5, -yModifier/6, -zRotationValue*5);
  }
  displace(0, -1, 0);
  for (let delta = 0; delta < 15; delta++) {
    generateSpinner(yModifier, delta);
    yModifier++;
  }
}

